// Jahbadh Lab catalog (served next to the lab files as `${BASE}/catalog.json`).
// Generated by packages/shared-utils/scripts/jahbadh-lab-catalog.ts; keep the shapes in sync with
// packages/shared-utils/src/jahbadh/lab-catalog.ts (it cannot import this package).
// An experiment opens at `${BASE}/${code}.html?lang=<ar|en|fr>`; BASE defaults to `/lab`.

export type LabLang = 'ar' | 'en' | 'fr'
export const LAB_LANGS: readonly LabLang[] = ['ar', 'en', 'fr']

export type LabKind = 'experiment' | 'simulation' | 'howto' | 'tool' | 'model'

export interface LabNames {
  ar: string
  en: string
  fr: string
}

export interface LabSubject extends LabNames {
  id: string
}

export interface LabGroup extends LabNames {
  id: string
  /** Id of the subject this group belongs to. */
  subject: string
}

/** School stage: `p` primary (1-6), `m` middle (7-9), `s` secondary (10-12). */
export interface LabLevel extends LabNames {
  id: string
}

export interface LabExperiment extends LabNames {
  code: string
  subject: string
  group: string
  /** Level ids the experiment suits, concatenated (e.g. "ms" = middle and secondary). Absent = all. */
  level?: string
  kind: LabKind
}

export interface LabCatalog {
  version: 1
  generated_at: string
  count: number
  subjects: LabSubject[]
  groups: LabGroup[]
  levels: LabLevel[]
  experiments: LabExperiment[]
}
